import { createHash } from "node:crypto";
import { compileSymbolicProgram } from "./symbolic-program.js";
import { parseSymbolicValues, runSymbolicSolver } from "./symbolic-solver.js";
import {
  type Scalar,
  type SymbolicRequest,
  type SymbolicResult,
  SymbolicUnsupported,
  symbolicLimits,
} from "./symbolic-types.js";
export type {
  SymbolicInput,
  SymbolicRequest,
  SymbolicResult,
} from "./symbolic-types.js";

const digest = (value: string) =>
  createHash("sha256").update(value).digest("hex");
const scope =
  "Only the selected scalar function body and supplied bounded integer/boolean inputs are modeled. Integers and every arithmetic intermediate stay within JavaScript's safe integer range. Calls, loops, mutation, globals, floats, NaN and Infinity are unsupported. A bounded result does not establish repository correctness, executed tests, source admission or user acceptance.";

export async function analyzeSymbolicSource(
  request: SymbolicRequest,
): Promise<SymbolicResult> {
  request = { ...request, inputs: structuredClone(request.inputs) };
  const base = {
    sourceSha256: digest(request.source),
    functionName: request.functionName,
    assertion: request.assertion,
    inputs: structuredClone(request.inputs),
    scope,
    validationAdmission: false as const,
  };
  const unknown = (
    reason: string,
    solver?: SymbolicResult["solver"],
  ): SymbolicResult => ({
    ...base,
    status: "unknown",
    reason,
    ...(solver ? { solver } : {}),
  });
  if (request.signal?.aborted) return unknown("cancelled");
  const timeoutMs = request.timeoutMs ?? symbolicLimits.defaultTimeoutMs;
  if (
    !Number.isInteger(timeoutMs) ||
    timeoutMs < 1 ||
    timeoutMs > symbolicLimits.maximumTimeoutMs
  )
    return unknown("invalid_timeout");
  let program: ReturnType<typeof compileSymbolicProgram>;
  try {
    program = compileSymbolicProgram(request);
  } catch (error) {
    return unknown(
      error instanceof SymbolicUnsupported
        ? error.message
        : "translation_failed",
    );
  }
  const executable = request.solverPath ?? process.env.BLAME_Z3_PATH ?? "z3";
  const started = Date.now();
  const identity = await runSymbolicSolver(executable, {
    timeoutMs,
    signal: request.signal,
  });
  if (identity.error) return unknown(identity.error);
  const version = identity.output.trim();
  if (!/^Z3 version \d+\.\d+\.\d+(?:[.\w -]*)$/.test(version))
    return unknown("unrecognized_solver_identity");
  const solver = { executable, version, querySha256: digest(program.query) };
  const remaining = timeoutMs - (Date.now() - started);
  if (remaining < 1) return unknown("timed_out", solver);
  const result = await runSymbolicSolver(executable, {
    query: program.query,
    values: program.variables.map((entry) => entry.smt),
    timeoutMs: remaining,
    signal: request.signal,
  });
  if (result.error) return unknown(result.error, solver);
  if (result.status === "unknown") return unknown("solver_unknown", solver);
  if (result.status === "unsat") {
    if (result.output.trim() !== "unsat")
      return unknown("invalid_solver_response", solver);
    return {
      ...base,
      solver,
      status: "bounded_no_counterexample",
      reason:
        "No violating input exists in the supplied finite safe integer/boolean domain under the supported isolated-function semantics.",
    };
  }
  if (result.status !== "sat")
    return unknown("invalid_solver_response", solver);
  try {
    const model = parseSymbolicValues(
      result.output,
      program.variables.map((entry) => entry.smt),
    );
    const inputs: Record<string, Scalar> = Object.fromEntries(
      program.variables.map((entry) => {
        const value = model.get(entry.smt)!;
        const contract = request.inputs[entry.name];
        if (
          entry.type === "boolean"
            ? typeof value !== "boolean"
            : typeof value !== "number" ||
              contract.type === "boolean" ||
              value < contract.min ||
              value > contract.max
        )
          throw new Error("model_outside_contract");
        return [entry.name, value];
      }),
    );
    const concrete = program.reproduce(inputs);
    if (concrete.assertion !== false)
      return unknown("counterexample_not_reproduced", solver);
    if (
      typeof concrete.result === "number" &&
      !Number.isSafeInteger(concrete.result)
    )
      return unknown("counterexample_outside_safe_integer_semantics", solver);
    return {
      ...base,
      solver,
      status: "counterexample",
      reason:
        "A violating input was reproduced by interpreting the original supported TypeScript AST with JavaScript scalar operations.",
      witness: {
        inputs,
        result: concrete.result,
        assertion: false,
        concretelyReproduced: true,
      },
    };
  } catch {
    return unknown("invalid_or_unreproduced_solver_model", solver);
  }
}

import ts from "typescript";
import {
  boundedSmt,
  compileExpression,
  evaluateExpression,
  smtInteger,
} from "./symbolic-expression.js";
import {
  type Bindings,
  type Environment,
  type Expression,
  type Scalar,
  type SymbolicRequest,
  symbolicLimits,
  unsupported,
} from "./symbolic-types.js";

type State = { env: Environment; path: string };
type Outcome = { path: string; value: Expression };
type FunctionNode =
  | ts.FunctionDeclaration
  | ts.ArrowFunction
  | ts.FunctionExpression;
export type SymbolicProgram = {
  query: string;
  variables: { name: string; smt: string; type: "integer" | "boolean" }[];
  reproduce(inputs: Record<string, Scalar>): {
    result: Scalar;
    assertion: Scalar;
  };
};

function parse(text: string) {
  const source = ts.createSourceFile(
    "symbolic.ts",
    text,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.TS,
  );
  if (
    (source as ts.SourceFile & { parseDiagnostics: readonly ts.Diagnostic[] })
      .parseDiagnostics.length
  )
    unsupported("source_parse_error");
  return source;
}

function scalarType(type: ts.TypeNode | undefined) {
  if (type?.kind === ts.SyntaxKind.NumberKeyword) return "integer";
  if (type?.kind === ts.SyntaxKind.BooleanKeyword) return "boolean";
  unsupported("explicit_scalar_parameter_type_required");
}

function findFunction(source: ts.SourceFile, name: string): FunctionNode {
  const found: (FunctionNode | undefined)[] = [];
  const bindingContains = (binding: ts.BindingName): boolean =>
    ts.isIdentifier(binding)
      ? binding.text === name
      : binding.elements.some(
          (element) =>
            !ts.isOmittedExpression(element) && bindingContains(element.name),
        );
  for (const statement of source.statements) {
    if (
      (ts.isClassDeclaration(statement) ||
        ts.isEnumDeclaration(statement) ||
        ts.isModuleDeclaration(statement)) &&
      statement.name?.getText(source) === name
    )
      found.push(undefined);
    if (ts.isImportDeclaration(statement) && statement.importClause) {
      const clause = statement.importClause,
        bindings = clause.namedBindings;
      if (
        clause.name?.text === name ||
        (bindings &&
          (ts.isNamespaceImport(bindings)
            ? bindings.name.text === name
            : bindings.elements.some((element) => element.name.text === name)))
      )
        found.push(undefined);
    }
    if (ts.isFunctionDeclaration(statement) && statement.name?.text === name)
      found.push(statement);
    if (ts.isVariableStatement(statement))
      for (const declaration of statement.declarationList.declarations)
        if (bindingContains(declaration.name))
          found.push(
            !statement.modifiers?.some(
              (modifier) =>
                modifier.kind === ts.SyntaxKind.DeclareKeyword ||
                modifier.kind === ts.SyntaxKind.AbstractKeyword,
            ) &&
              ts.isIdentifier(declaration.name) &&
              statement.declarationList.flags & ts.NodeFlags.Const &&
              declaration.initializer &&
              (ts.isArrowFunction(declaration.initializer) ||
                ts.isFunctionExpression(declaration.initializer))
              ? declaration.initializer
              : undefined,
          );
  }
  if (found.length !== 1 || !found[0])
    unsupported("function_missing_ambiguous_or_unsupported");
  return found[0];
}

export function compileSymbolicProgram(
  request: SymbolicRequest,
): SymbolicProgram {
  if (Buffer.byteLength(request.source) > symbolicLimits.sourceBytes)
    unsupported("source_size_limit");
  if (!/^[A-Za-z_$][\w$]{0,127}$/.test(request.functionName))
    unsupported("invalid_function_name");
  if (request.assertion.length > symbolicLimits.assertionCharacters)
    unsupported("assertion_size_limit");
  const node = findFunction(parse(request.source), request.functionName);
  if (
    !node.body ||
    node.typeParameters?.length ||
    ("asteriskToken" in node && node.asteriskToken) ||
    node.modifiers?.some((modifier) =>
      [
        ts.SyntaxKind.AsyncKeyword,
        ts.SyntaxKind.DeclareKeyword,
        ts.SyntaxKind.AbstractKeyword,
      ].includes(modifier.kind),
    )
  )
    unsupported("unsupported_function_shape");
  if (node.getWidth() > symbolicLimits.targetCharacters)
    unsupported("target_size_limit");
  if (
    node.type &&
    ![ts.SyntaxKind.NumberKeyword, ts.SyntaxKind.BooleanKeyword].includes(
      node.type.kind,
    )
  )
    unsupported("unsupported_return_type");
  let nodes = 0;
  const count = (item: ts.Node) => {
    nodes++;
    ts.forEachChild(item, count);
  };
  count(node);
  if (nodes > symbolicLimits.nodes) unsupported("syntax_node_limit");
  const env: Environment = new Map();
  const variables: SymbolicProgram["variables"] = [];
  const constraints: string[] = [];
  const names = new Set<string>(["result"]);
  if (
    !node.parameters.length ||
    node.parameters.length > symbolicLimits.inputs ||
    Object.keys(request.inputs).length !== node.parameters.length
  )
    unsupported("input_contract_mismatch");
  for (const [index, parameter] of node.parameters.entries()) {
    if (
      !ts.isIdentifier(parameter.name) ||
      parameter.questionToken ||
      parameter.dotDotDotToken ||
      parameter.initializer ||
      parameter.modifiers?.length
    )
      unsupported("unsupported_parameter");
    const name = parameter.name.text;
    if (
      name === "this" ||
      names.has(name) ||
      !Object.hasOwn(request.inputs, name)
    )
      unsupported("input_contract_mismatch");
    names.add(name);
    const type = scalarType(parameter.type),
      contract = request.inputs[name],
      smt = `p${index}`;
    if (type === "boolean") {
      if (contract.type !== "boolean")
        unsupported("input_contract_type_mismatch");
      env.set(name, { type, smt });
    } else {
      if (
        contract.type === "boolean" ||
        !Number.isSafeInteger(contract.min) ||
        !Number.isSafeInteger(contract.max) ||
        contract.min > contract.max
      )
        unsupported("finite_safe_integer_bounds_required");
      env.set(name, {
        type,
        smt,
        min: BigInt(contract.min),
        max: BigInt(contract.max),
      });
      constraints.push(
        `(assert (and (<= ${smtInteger(BigInt(contract.min))} ${smt}) (<= ${smt} ${smtInteger(BigInt(contract.max))})))`,
      );
    }
    variables.push({ name, smt, type });
  }
  const outcomes: Outcome[] = [];
  let expansions = 0;
  const execute = (statement: ts.Statement, state: State): State[] => {
    if (++expansions > symbolicLimits.nodes)
      unsupported("symbolic_expansion_limit");
    if (ts.isReturnStatement(statement)) {
      if (!statement.expression) unsupported("return_expression_required");
      outcomes.push({
        path: state.path,
        value: compileExpression(statement.expression, state.env),
      });
      if (outcomes.length > symbolicLimits.paths)
        unsupported("symbolic_path_limit");
      return [];
    }
    if (ts.isBlock(statement)) {
      const remaining = statements(statement.statements, {
        ...state,
        env: new Map(state.env),
      });
      return remaining.map((entry) => ({ ...entry, env: new Map(state.env) }));
    }
    if (ts.isIfStatement(statement)) {
      const condition = compileExpression(statement.expression, state.env);
      if (condition.type !== "boolean")
        unsupported("boolean_condition_required");
      const branch = (path: string) => ({
        env: new Map(state.env),
        path: boundedSmt(`(and ${state.path} ${path})`),
      });
      const yes = execute(statement.thenStatement, branch(condition.smt));
      const noState = branch(`(not ${condition.smt})`);
      return [
        ...yes,
        ...(statement.elseStatement
          ? execute(statement.elseStatement, noState)
          : [noState]),
      ];
    }
    if (
      ts.isVariableStatement(statement) &&
      statement.declarationList.flags & ts.NodeFlags.Const
    ) {
      for (const declaration of statement.declarationList.declarations) {
        if (!ts.isIdentifier(declaration.name) || !declaration.initializer)
          unsupported("unsupported_local_declaration");
        const name = declaration.name.text;
        // A declaration may be visited in several paths, but scope shadowing is rejected below.
        const value = compileExpression(declaration.initializer, state.env);
        if (declaration.type && scalarType(declaration.type) !== value.type)
          unsupported("local_type_mismatch");
        state.env.set(name, value);
      }
      return [state];
    }
    unsupported(`unsupported_statement:${ts.SyntaxKind[statement.kind]}`);
  };
  const statements = (
    items: readonly ts.Statement[],
    initial: State,
  ): State[] => {
    let active = [initial];
    for (const item of items) {
      if (!active.length) unsupported("unreachable_statement");
      active = active.flatMap((state) => execute(item, state));
      if (active.length > symbolicLimits.paths)
        unsupported("symbolic_path_limit");
    }
    return active;
  };
  const checkNames = (item: ts.Node) => {
    if (ts.isVariableDeclaration(item)) {
      if (!ts.isIdentifier(item.name) || names.has(item.name.text))
        unsupported("shadowed_or_duplicate_local");
      names.add(item.name.text);
    }
    ts.forEachChild(item, checkNames);
  };
  checkNames(node.body);
  if (ts.isBlock(node.body)) {
    if (
      statements(node.body.statements, { env: new Map(env), path: "true" })
        .length
    )
      unsupported("all_paths_must_return");
  } else
    outcomes.push({ path: "true", value: compileExpression(node.body, env) });
  if (!outcomes.length) unsupported("all_paths_must_return");
  if (
    node.type &&
    outcomes.some((outcome) => outcome.value.type !== scalarType(node.type))
  )
    unsupported("return_type_mismatch");
  let result = outcomes.at(-1)!.value;
  for (const outcome of outcomes.slice(0, -1).reverse()) {
    if (outcome.value.type !== result.type) unsupported("mixed_return_types");
    result = {
      ...result,
      smt: boundedSmt(
        `(ite ${outcome.path} ${outcome.value.smt} ${result.smt})`,
      ),
    };
  }
  const assertionSource = parse(`const __assertion = (${request.assertion});`);
  if (
    assertionSource.statements.length !== 1 ||
    !ts.isVariableStatement(assertionSource.statements[0]) ||
    assertionSource.statements[0].declarationList.declarations.length !== 1
  )
    unsupported("assertion_expression_required");
  const assertion =
    assertionSource.statements[0].declarationList.declarations[0].initializer;
  if (
    !assertion ||
    !ts.isParenthesizedExpression(assertion) ||
    assertion.getStart(assertionSource) !== "const __assertion = ".length ||
    assertion.getText(assertionSource) !== `(${request.assertion})`
  )
    unsupported("assertion_expression_required");
  const assertionEnv = new Map(env);
  if (result.type === "integer") {
    const integers = outcomes
      .map((entry) => entry.value)
      .filter((value) => value.type === "integer");
    result = {
      ...result,
      min: integers.reduce(
        (min, value) => (value.min < min ? value.min : min),
        result.min,
      ),
      max: integers.reduce(
        (max, value) => (value.max > max ? value.max : max),
        result.max,
      ),
    };
  }
  assertionEnv.set("result", result);
  const property = compileExpression(assertion, assertionEnv);
  if (property.type !== "boolean") unsupported("boolean_assertion_required");
  const query = [
    "(set-logic QF_NIA)",
    ...variables.map(
      (entry) =>
        `(declare-const ${entry.smt} ${entry.type === "integer" ? "Int" : "Bool"})`,
    ),
    ...constraints,
    `(assert (not ${property.smt}))`,
  ].join("\n");
  if (Buffer.byteLength(query) > symbolicLimits.maximumSmtBytes)
    unsupported("smt_size_limit");
  return {
    query,
    variables,
    reproduce: (inputs) => {
      const bindings: Bindings = new Map(Object.entries(inputs));
      const value = evaluateFunction(node, bindings);
      bindings.set("result", value);
      return {
        result: value,
        assertion: evaluateExpression(assertion, bindings),
      };
    },
  };
}

function evaluateFunction(node: FunctionNode, env: Bindings): Scalar {
  const run = (
    statement: ts.Statement,
    bindings: Bindings,
  ): { value: Scalar } | undefined => {
    if (ts.isReturnStatement(statement) && statement.expression)
      return { value: evaluateExpression(statement.expression, bindings) };
    if (ts.isBlock(statement)) {
      const nested = new Map(bindings);
      for (const item of statement.statements) {
        const result = run(item, nested);
        if (result) return result;
      }
      return;
    }
    if (ts.isIfStatement(statement)) {
      if (evaluateExpression(statement.expression, bindings))
        return run(statement.thenStatement, bindings);
      if (statement.elseStatement)
        return run(statement.elseStatement, bindings);
      return;
    }
    if (ts.isVariableStatement(statement)) {
      for (const declaration of statement.declarationList.declarations)
        if (ts.isIdentifier(declaration.name) && declaration.initializer)
          bindings.set(
            declaration.name.text,
            evaluateExpression(declaration.initializer, bindings),
          );
      return;
    }
    unsupported("concrete_unsupported_statement");
  };
  if (!node.body) unsupported("concrete_missing_body");
  if (!ts.isBlock(node.body)) return evaluateExpression(node.body, env);
  const value = run(node.body, env);
  if (!value) unsupported("concrete_missing_return");
  return value.value;
}

import ts from "typescript";
import {
  type Bindings,
  type Environment,
  type Expression,
  type Scalar,
  symbolicLimits,
  unsupported,
} from "./symbolic-types.js";

const safe = BigInt(Number.MAX_SAFE_INTEGER);
export const smtInteger = (value: bigint) =>
  value < 0n ? `(- ${-value})` : String(value);

export function boundedSmt(smt: string): string {
  if (smt.length > symbolicLimits.maximumSmtBytes)
    unsupported("smt_size_limit");
  return smt;
}

function boolean(smt: string): Expression {
  return { type: "boolean", smt: boundedSmt(smt) };
}

function integer(smt: string, min: bigint, max: bigint): Expression {
  if (min < -safe || max > safe) unsupported("unsafe_integer_intermediate");
  return { type: "integer", smt: boundedSmt(smt), min, max };
}

export function compileExpression(
  node: ts.Expression,
  env: Environment,
): Expression {
  if (ts.isParenthesizedExpression(node))
    return compileExpression(node.expression, env);
  if (ts.isIdentifier(node)) {
    const value = env.get(node.text);
    if (!value) unsupported(`unbound_identifier:${node.text}`);
    return value;
  }
  if (ts.isNumericLiteral(node)) {
    const value = Number(node.text);
    if (!Number.isSafeInteger(value)) unsupported("non_safe_integer_literal");
    return integer(smtInteger(BigInt(value)), BigInt(value), BigInt(value));
  }
  if (
    node.kind === ts.SyntaxKind.TrueKeyword ||
    node.kind === ts.SyntaxKind.FalseKeyword
  )
    return boolean(node.kind === ts.SyntaxKind.TrueKeyword ? "true" : "false");
  if (ts.isPrefixUnaryExpression(node)) {
    const value = compileExpression(node.operand, env);
    if (
      node.operator === ts.SyntaxKind.ExclamationToken &&
      value.type === "boolean"
    )
      return boolean(`(not ${value.smt})`);
    if (value.type !== "integer") unsupported("unary_operand_type");
    if (node.operator === ts.SyntaxKind.PlusToken) return value;
    if (node.operator === ts.SyntaxKind.MinusToken)
      return integer(`(- ${value.smt})`, -value.max, -value.min);
    unsupported("unsupported_unary_operator");
  }
  if (ts.isConditionalExpression(node)) {
    const condition = compileExpression(node.condition, env);
    const yes = compileExpression(node.whenTrue, env);
    const no = compileExpression(node.whenFalse, env);
    if (condition.type !== "boolean" || yes.type !== no.type)
      unsupported("conditional_operand_type");
    const smt = `(ite ${condition.smt} ${yes.smt} ${no.smt})`;
    return yes.type === "integer" && no.type === "integer"
      ? integer(
          smt,
          yes.min < no.min ? yes.min : no.min,
          yes.max > no.max ? yes.max : no.max,
        )
      : boolean(smt);
  }
  if (!ts.isBinaryExpression(node))
    unsupported(`unsupported_expression:${ts.SyntaxKind[node.kind]}`);
  const a = compileExpression(node.left, env);
  const b = compileExpression(node.right, env);
  const operator = node.operatorToken.kind;
  const equality =
    operator === ts.SyntaxKind.EqualsEqualsEqualsToken ||
    operator === ts.SyntaxKind.ExclamationEqualsEqualsToken;
  if (equality) {
    if (a.type !== b.type) unsupported("equality_operand_type");
    const smt = `(= ${a.smt} ${b.smt})`;
    return boolean(
      operator === ts.SyntaxKind.EqualsEqualsEqualsToken ? smt : `(not ${smt})`,
    );
  }
  if (
    operator === ts.SyntaxKind.AmpersandAmpersandToken ||
    operator === ts.SyntaxKind.BarBarToken
  ) {
    if (a.type !== "boolean" || b.type !== "boolean")
      unsupported("logical_operand_type");
    return boolean(
      `(${operator === ts.SyntaxKind.AmpersandAmpersandToken ? "and" : "or"} ${a.smt} ${b.smt})`,
    );
  }
  if (a.type !== "integer" || b.type !== "integer")
    unsupported("integer_operand_type");
  const comparisons = new Map([
    [ts.SyntaxKind.LessThanToken, "<"],
    [ts.SyntaxKind.LessThanEqualsToken, "<="],
    [ts.SyntaxKind.GreaterThanToken, ">"],
    [ts.SyntaxKind.GreaterThanEqualsToken, ">="],
  ]);
  const comparison = comparisons.get(operator);
  if (comparison) return boolean(`(${comparison} ${a.smt} ${b.smt})`);
  if (operator === ts.SyntaxKind.PlusToken)
    return integer(`(+ ${a.smt} ${b.smt})`, a.min + b.min, a.max + b.max);
  if (operator === ts.SyntaxKind.MinusToken)
    return integer(`(- ${a.smt} ${b.smt})`, a.min - b.max, a.max - b.min);
  if (operator === ts.SyntaxKind.AsteriskToken) {
    const bounds = [a.min * b.min, a.min * b.max, a.max * b.min, a.max * b.max];
    return integer(
      `(* ${a.smt} ${b.smt})`,
      bounds.reduce((x, y) => (x < y ? x : y)),
      bounds.reduce((x, y) => (x > y ? x : y)),
    );
  }
  unsupported("unsupported_binary_operator");
}

// This interpreter evaluates the original supported AST using JavaScript scalar
// operations. It does not evaluate SMT or dynamically execute repository code.
export function evaluateExpression(node: ts.Expression, env: Bindings): Scalar {
  if (ts.isParenthesizedExpression(node))
    return evaluateExpression(node.expression, env);
  if (ts.isIdentifier(node)) {
    if (!env.has(node.text)) unsupported("concrete_unbound_identifier");
    return env.get(node.text)!;
  }
  if (ts.isNumericLiteral(node)) return Number(node.text);
  if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
  if (node.kind === ts.SyntaxKind.FalseKeyword) return false;
  if (ts.isPrefixUnaryExpression(node)) {
    const value = evaluateExpression(node.operand, env);
    if (node.operator === ts.SyntaxKind.ExclamationToken) return !value;
    if (typeof value !== "number") unsupported("concrete_unary_type");
    if (node.operator === ts.SyntaxKind.MinusToken) return -value;
    if (node.operator === ts.SyntaxKind.PlusToken) return +value;
  }
  if (ts.isConditionalExpression(node))
    return evaluateExpression(
      evaluateExpression(node.condition, env) ? node.whenTrue : node.whenFalse,
      env,
    );
  if (ts.isBinaryExpression(node)) {
    const a = evaluateExpression(node.left, env);
    const op = node.operatorToken.kind;
    if (op === ts.SyntaxKind.AmpersandAmpersandToken)
      return a && evaluateExpression(node.right, env);
    if (op === ts.SyntaxKind.BarBarToken)
      return a || evaluateExpression(node.right, env);
    const b = evaluateExpression(node.right, env);
    if (op === ts.SyntaxKind.EqualsEqualsEqualsToken) return a === b;
    if (op === ts.SyntaxKind.ExclamationEqualsEqualsToken) return a !== b;
    if (typeof a !== "number" || typeof b !== "number")
      unsupported("concrete_integer_type");
    if (op === ts.SyntaxKind.PlusToken) return a + b;
    if (op === ts.SyntaxKind.MinusToken) return a - b;
    if (op === ts.SyntaxKind.AsteriskToken) return a * b;
    if (op === ts.SyntaxKind.LessThanToken) return a < b;
    if (op === ts.SyntaxKind.LessThanEqualsToken) return a <= b;
    if (op === ts.SyntaxKind.GreaterThanToken) return a > b;
    if (op === ts.SyntaxKind.GreaterThanEqualsToken) return a >= b;
  }
  unsupported("concrete_unsupported_expression");
}

import { spawn } from "node:child_process";
import { symbolicLimits } from "./symbolic-types.js";

type ProcessResult = {
  output: string;
  error?: string;
  status?: "sat" | "unsat" | "unknown";
};
export function runSymbolicSolver(
  executable: string,
  options: {
    query?: string;
    values?: string[];
    timeoutMs: number;
    signal?: AbortSignal;
  },
): Promise<ProcessResult> {
  if (options.signal?.aborted)
    return Promise.resolve({ output: "", error: "cancelled" });
  return new Promise((resolve) => {
    const child = spawn(
      executable,
      options.query ? ["-in", "-smt2"] : ["-version"],
      {
        shell: false,
        detached: process.platform !== "win32",
        stdio: ["pipe", "pipe", "pipe"],
        windowsHide: true,
      },
    );
    let output = "",
      stderr = "",
      bytes = 0,
      error: string | undefined;
    let status: ProcessResult["status"],
      finished = false,
      drain: NodeJS.Timeout | undefined;
    const stop = (reason: string) => {
      error ??= reason;
      if (process.platform !== "win32" && child.pid) {
        try {
          process.kill(-child.pid, "SIGKILL");
        } catch {
          child.kill("SIGKILL");
        }
      } else child.kill("SIGKILL");
      drain ??= setTimeout(() => finish(), 100);
    };
    const abort = () => stop("cancelled");
    const timer = setTimeout(() => stop("timed_out"), options.timeoutMs);
    const finish = (code?: number | null) => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      clearTimeout(drain);
      options.signal?.removeEventListener("abort", abort);
      child.stdin.destroy();
      child.stdout.destroy();
      child.stderr.destroy();
      child.unref();
      if (!error && code !== 0) error = "solver_process_failed";
      if (!error && stderr.trim()) error = "solver_stderr";
      resolve({
        output,
        ...(status ? { status } : {}),
        ...(error ? { error } : {}),
      });
    };
    const capture = (chunk: Buffer, isError: boolean) => {
      if (finished) return;
      bytes += chunk.length;
      if (bytes > symbolicLimits.outputBytes) {
        stop("output_limit");
        return;
      }
      if (isError) {
        stderr += chunk.toString("utf8");
        return;
      }
      output += chunk.toString("utf8");
      if (!options.query || status) return;
      const first = /^(sat|unsat|unknown)\r?\n/.exec(output);
      if (!first) {
        if (output.includes("\n")) stop("invalid_solver_status");
        return;
      }
      status = first[1] as NonNullable<ProcessResult["status"]>;
      child.stdin.end(
        status === "sat"
          ? `(get-value (${options.values!.join(" ")}))\n(exit)\n`
          : "(exit)\n",
      );
    };
    child.stdout.on("error", () => {
      if (!finished) stop("solver_output_failed");
    });
    child.stderr.on("error", () => {
      if (!finished) stop("solver_output_failed");
    });
    child.stdout.on("data", (chunk: Buffer) => capture(chunk, false));
    child.stderr.on("data", (chunk: Buffer) => capture(chunk, true));
    child.on("error", (cause: NodeJS.ErrnoException) => {
      error =
        cause.code === "ENOENT" ? "solver_unavailable" : "solver_spawn_failed";
      finish();
    });
    child.stdin.on("error", () => {
      if (!finished) stop("solver_input_failed");
    });
    child.once("close", finish);
    options.signal?.addEventListener("abort", abort, { once: true });
    if (options.signal?.aborted) abort();
    else if (options.query)
      child.stdin.write(
        `(set-option :timeout ${options.timeoutMs})\n${options.query}\n(check-sat)\n`,
      );
    else child.stdin.end();
  });
}

export function parseSymbolicValues(
  output: string,
  names: string[],
): Map<string, number | boolean> {
  const text = output.replace(/^sat\r?\n/, "").trim();
  if (text.length > symbolicLimits.outputBytes || !/^\([\s\S]*\)$/.test(text))
    throw new Error("invalid_solver_model");
  const values = new Map<string, number | boolean>();
  const remaining = text
    .slice(1, -1)
    .replace(
      /\(\s*(p\d+)\s+(true|false|-?\d+|\(\s*-\s+\d+\s*\))\s*\)/g,
      (_all, name: string, literal: string) => {
        if (!names.includes(name) || values.has(name))
          throw new Error("invalid_solver_model");
        const value =
          literal === "true"
            ? true
            : literal === "false"
              ? false
              : literal.startsWith("(")
                ? -Number(literal.replace(/[()\s-]/g, ""))
                : Number(literal);
        if (typeof value === "number" && !Number.isSafeInteger(value))
          throw new Error("invalid_solver_model");
        values.set(name, value);
        return "";
      },
    );
  if (remaining.trim() || values.size !== names.length)
    throw new Error("invalid_solver_model");
  return values;
}

export type SymbolicInput =
  | { min: number; max: number; type?: "integer" }
  | { type: "boolean" };

export type SymbolicRequest = {
  source: string;
  functionName: string;
  inputs: Record<string, SymbolicInput>;
  assertion: string;
  timeoutMs?: number;
  signal?: AbortSignal;
  solverPath?: string;
};

export type SymbolicResult = {
  status: "counterexample" | "bounded_no_counterexample" | "unknown";
  reason: string;
  sourceSha256: string;
  functionName: string;
  assertion: string;
  inputs: Record<string, SymbolicInput>;
  scope: string;
  validationAdmission: false;
  solver?: { executable: string; version: string; querySha256: string };
  witness?: {
    inputs: Record<string, number | boolean>;
    result: number | boolean;
    assertion: false;
    concretelyReproduced: true;
  };
};

export type Scalar = number | boolean;
export type Bindings = Map<string, Scalar>;
export type IntegerExpression = {
  type: "integer";
  smt: string;
  min: bigint;
  max: bigint;
};
export type BooleanExpression = { type: "boolean"; smt: string };
export type Expression = IntegerExpression | BooleanExpression;
export type Environment = Map<string, Expression>;
export const symbolicLimits = {
  sourceBytes: 256 * 1024,
  targetCharacters: 16 * 1024,
  assertionCharacters: 4096,
  nodes: 512,
  paths: 32,
  inputs: 8,
  maximumSmtBytes: 128 * 1024,
  outputBytes: 64 * 1024,
  defaultTimeoutMs: 2500,
  maximumTimeoutMs: 10_000,
};

export class SymbolicUnsupported extends Error {}
export function unsupported(reason: string): never {
  throw new SymbolicUnsupported(reason);
}
